// Bundles legacy samples, golden runs and the sandbox POM template into TypeScript modules
// consumed by the Lambda handlers (services) and the web app.
import { readFileSync, readdirSync, statSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { join, relative } from 'node:path';

const root = new URL('..', import.meta.url).pathname;

function walk(dir) {
  const out = [];
  for (const name of readdirSync(dir).sort()) {
    if (name === 'target' || name.startsWith('.')) continue;
    const p = join(dir, name);
    if (statSync(p).isDirectory()) out.push(...walk(p));
    else out.push(p);
  }
  return out;
}

const samples = {};
for (const id of readdirSync(join(root, 'legacy-samples')).sort()) {
  const dir = join(root, 'legacy-samples', id);
  const meta = JSON.parse(readFileSync(join(dir, 'sample.json'), 'utf8'));
  const files = walk(dir)
    .filter((p) => !p.endsWith('sample.json'))
    .map((p) => ({ path: relative(dir, p), content: readFileSync(p, 'utf8') }));
  samples[id] = { ...meta, files };
}

const golden = {};
for (const id of readdirSync(join(root, 'golden-runs')).sort()) {
  const dir = join(root, 'golden-runs', id);
  const ressPath = join(dir, 'ress.json');
  if (!existsSync(ressPath)) continue;
  const modernDir = join(dir, 'modern');
  golden[id] = {
    ress: JSON.parse(readFileSync(ressPath, 'utf8')),
    annotations: JSON.parse(readFileSync(join(dir, 'annotations.json'), 'utf8')),
    files: walk(modernDir).map((p) => ({ path: relative(modernDir, p), content: readFileSync(p, 'utf8') })),
  };
}

const pomTemplate = readFileSync(join(root, 'sandbox-image', 'pom-template.xml'), 'utf8');

const banner = '// AUTO-GENERATED by scripts/gen-bundle.mjs — do not edit.\n';
mkdirSync(join(root, 'services/src/generated'), { recursive: true });
writeFileSync(
  join(root, 'services/src/generated/bundle.ts'),
  banner +
    `import type { Sample, Ress, FileAnnotation, SourceFile } from '../lib/types';\n` +
    `export const SAMPLES: Record<string, Sample> = ${JSON.stringify(samples)};\n` +
    `export const GOLDEN: Record<string, { ress: Ress; annotations: FileAnnotation[]; files: SourceFile[] }> = ${JSON.stringify(golden)};\n` +
    `export const POM_TEMPLATE: string = ${JSON.stringify(pomTemplate)};\n`,
);

mkdirSync(join(root, 'web/src/generated'), { recursive: true });
writeFileSync(join(root, 'web/src/generated/prd.ts'), banner + `export const PRD_MARKDOWN: string = ${JSON.stringify(readFileSync(join(root, 'docs/PRD.md'), 'utf8'))};\n`);
console.log(`bundled ${Object.keys(samples).length} samples, ${Object.keys(golden).length} golden runs`);
